using System;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {public static class VehiclePlateFinish {
 public static void Apply(GameObject root){var legacy=root.transform.Find("AG_Photorealistic3D_Assets");foreach(Transform t in legacy)if(t.name=="AG_Tucson_LicensePlate"||t.name=="AG_SecondCar_LicensePlate")t.gameObject.SetActive(false);var layout=root.GetComponentInChildren<ParkingTrainingLayout>();int index=0;foreach(var obstacle in layout.obstacles){if(obstacle.id.Contains("PortedModel")||obstacle.id.Contains("BoxTruck"))continue;var car=layout.transform.Find(obstacle.id);var b=ContextBuilder.BoundsOf(car.gameObject);var material=new Material(Shader.Find("Standard")){name="AttachedPlate_"+index,color=new Color(.88f,.88f,.86f)};material.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(ContextBuilder.W+"/Plate_"+index+".png");material.SetFloat("_Glossiness",.3f);AssetDatabase.CreateAsset(material,ContextBuilder.W+"/AttachedPlate_"+index+".mat");bool parallel=obstacle.id.StartsWith("Parked_P_");bool suv=obstacle.category=="SUV";foreach(int sign in new[]{-1,1}){var plate=GameObject.CreatePrimitive(PrimitiveType.Quad);plate.name=sign>0?"AttachedFrontPlate":"AttachedRearPlate";plate.transform.SetParent(car,false);float y=sign>0?(suv?.50f:.43f):(suv?.61f:.55f);if(!parallel){plate.transform.position=new Vector3(sign>0?b.max.x+.016f:b.min.x-.016f,y,b.center.z);plate.transform.rotation=Quaternion.Euler(0,sign>0?-90:90,0);}else{plate.transform.position=new Vector3(b.center.x,y,sign>0?b.min.z-.016f:b.max.z+.016f);plate.transform.rotation=Quaternion.Euler(0,sign>0?0:180,0);}plate.transform.localScale=new Vector3(.52f,.11f,1);UnityEngine.Object.DestroyImmediate(plate.GetComponent<Collider>());plate.GetComponent<Renderer>().sharedMaterial=material;plate.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;GameObjectUtility.SetStaticEditorFlags(plate,StaticEditorFlags.ReflectionProbeStatic);}index++;}}
}}
